?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>سجل الحضور | HERA</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="/BIC2_Mvp/assets/hera-brand.css"><script src="/BIC2_Mvp/assets/hera-language.js" defer></script></head><body class="hera-theme min-h-screen"><header class="border-b border-slate-200 bg-white/90"><div class="max-w-6xl mx-auto px-5 py-4 flex items-center justify-between gap-4"><a class="flex items-center gap-3" href="/BIC2_Mvp/employee.php"><img src="/BIC2_Mvp/assets/hera-mark.svg" class="w-10 h-10 object-contain" alt="HERA"><span><b class="block">HERA</b><small class="text-slate-500">بوابة الموظف</small></span></a><nav class="flex flex-wrap gap-2 text-sm"><a class="px-3 py-2 rounded-xl" href="/BIC2_Mvp/employee.php">الرئيسية</a><a class="px-3 py-2 rounded-xl" href="/BIC2_Mvp/leaves.php">الإجازات</a><a class="px-3 py-2 rounded-xl" href="/BIC2_Mvp/payroll.php">الراتب</a><a class="px-3 py-2 rounded-xl" href="/BIC2_Mvp/notifications.php">الإشعارات</a></nav></div></header><main class="max-w-6xl mx-auto p-5 sm:p-8"><div class="mb-6"><p class="text-xs font-bold tracking-widest text-slate-500">HERA · ATTENDANCE</p><h1 class="text-2xl font-bold mt-2">سجل الحضور والانصراف</h1><p class="text-sm text-slate-500 mt-2">سجلات آخر 30 يومًا</p></div><section class="card overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr><th class="px-5 py-3 text-right">التاريخ</th><th class="px-5 py-3 text-right">وقت الدخول</th><th class="px-5 py-3 text-right">الاستراحة</th><th class="px-5 py-3 text-right">وقت الخروج</th><th class="px-5 py-3 text-right">المسافة</th><th class="px-5 py-3 text-right">الحالة</th></tr></thead><tbody id="attendanceRows"><tr><td colspan="6" class="text-center py-8 text-slate-500">جارٍ التحميل...</td></tr></tbody></table></div></section></main><script>
const body=document.getElementById('attendanceRows');
const safe=v=>{const n=document.createElement('span');n.textContent=v??'';return n.innerHTML};
fetch('/BIC2_Mvp/api/attendance.php?action=history').then(r=>r.json()).then(data=>{if(!data.success||!data.records?.length){body.innerHTML='<tr><td colspan="6" class="text-center py-8 text-slate-500">لا توجد سجلات حضور حتى الآن.</td></tr>';return}const labels={present:'حاضر',late:'متأخر',absent:'غائب'};body.innerHTML=data.records.map(r=>{const br=r.break_start_time?`${r.break_start_time.slice(0,5)} - ${r.break_end_time?r.break_end_time.slice(0,5):'مستمر'}`:'—';return `<tr><td class="px-5 py-3">${safe(r.date)}</td><td class="px-5 py-3">${safe(r.check_in_time?.slice(0,5)||'—')}</td><td class="px-5 py-3">${safe(br)}</td><td class="px-5 py-3">${safe(r.check_out_time?.slice(0,5)||'—')}</td><td class="px-5 py-3">${r.distance_in_meters?`${safe(r.distance_in_meters)} م`:'—'}</td><td class="px-5 py-3">${safe(labels[r.status]||r.status)}</td></tr>`}).join('')}).catch(()=>{body.innerHTML='<tr><td colspan="6" class="text-center py-8 text-slate-500">تعذر تحميل السجل الآن.</td></tr>'});
</script></body></html>